def sub(label,text):
 global s
 start=s.index('\\label{'+label+'}')+len('\\label{'+label+'}')
 end=re.search(r'\\(?:subsection|section|appendices|bibliographystyle)\b',s[start:])
 assert end,label
 s=s[:start]+'\n\n'+text.strip()+'\n\n'+s[start+end.start():]
def env(label,new,kind='table'):
 global s
 pat=r'\\begin\{'+kind+r'\*?\}.*?\\end\{'+kind+r'\*?\}'
 matches=[m for m in re.finditer(pat,s,re.S) if '\\label{'+label+'}' in m.group()]
 assert len(matches)==1,(label,len(matches))
 m=matches[0];s=s[:m.start()]+new+s[m.end():]
def fmt(n,m='test_bal_acc',scale=100):return f'${n[m+"_mean"]*scale:.2f}\\pm{n[m+"_std"]*scale:.2f}$'
def table(label,caption,heads,rows,width=False,note='',size='footnotesize'):
 kind='table*' if width else 'table';cols='l'+'c'*(len(heads)-1)
 return '\n'.join(['\\begin{'+kind+'}[t]','\\centering','\\'+size,'\\caption{'+caption+'}','\\label{'+label+'}',r'\renewcommand{\arraystretch}{1.12}',r'\setlength{\tabcolsep}{3pt}','\\begin{tabular}{'+cols+'}',r'\hline',' & '.join(heads)+r' \\',r'\hline',*[' & '.join(map(str,row))+r' \\' for row in rows],r'\hline',r'\end{tabular}',r'\par\smallskip\begin{minipage}{\linewidth}\footnotesize '+note+r'\end{minipage}' if note else '',r'\end{'+kind+'}'])
def fig(label,file,caption,wide=True):
 k='figure*' if wide else 'figure';return '\n'.join(['\\begin{'+k+'}[t]',r'\centering',r'\includegraphics[width=\linewidth]{figs_revised/'+file+'.pdf}',r'\caption{'+caption+'}',r'\label{'+label+'}',r'\end{'+k+'}'])
def group(title,n):return [r'\multicolumn{'+str(n)+r'}{c}{\textit{'+title+'}}']+['']*(n-1)
# Abstract and introductory contribution claims.
abstract=r'''This paper evaluates false-data-injection attack (FDIA) detection and injected-bias severity assessment in heterogeneous inverter-fed drives using trusted motor-terminal or point-of-common-coupling (PCC) measurements. Low-frequency, high-frequency, and time-domain features are combined with an InceptionTime classifier. Laboratory data comprise 18 recordings from an alternating current induction motor (ACIM) and a permanent magnet synchronous motor (PMSM), covering three speeds and three load settings. Training, validation, and testing use disjoint recordings and episodes, with three repeated holdouts. Mean binary detection accuracy is 87.41\% for motor-side sensing and 80.78\% for PCC sensing; corresponding four-class severity balanced accuracies are 90.81\% and 55.62\%. The proposed model attains the highest mean PCC balanced accuracy among the evaluated baselines, although it does not lead every severity metric. The PCC severity model identifies 61.39\%, 85.08\%, and 88.09\% of low-, medium-, and high-bias attacks as attacks, respectively, with a 37.23\% normal false-alarm rate. Supervised PMSM-to-ACIM fine-tuning reaches 91.38\% PCC balanced accuracy at a nominal 20\% target adaptation budget, while the reverse direction remains difficult. Removing high-frequency features reduces PCC processing time from 22.37 to 12.32~ms with similar detection balanced accuracy. These results characterize the capabilities and limitations of PCC monitoring on the tested platform under additive feedback-bias attacks.'''
s=re.sub(r'\\begin\{abstract\}.*?\\end\{abstract\}',lambda _:r'\begin{abstract}'+'\n'+abstract+'\n'+r'\end{abstract}',s,flags=re.S)
s=s.replace('LF), high-frequency (HF), and time-domain (TD) current features','LF), high-frequency (HF), and time-domain (TD) electrical features')
s=s.replace('The study evaluates binary detection, four-level severity assessment, cross-domain transfer, and deployment feasibility.','The study evaluates binary detection, four-level injected-bias assessment, cross-domain transfer, and processing cost for converter-fed industrial loads connected at a shared electrical interface.')
a=s.index('\\begin{itemize}',s.index('\\label{sec:contributions}'));b=s.index('\\end{itemize}',a)+len('\\end{itemize}')
s=s[:a]+r'''\begin{itemize}
\item \textbf{Evaluated} nonintrusive PCC-based FDIA detection on a heterogeneous ACIM/PMSM laboratory platform using whole-recording holdouts that also keep all constituent episodes disjoint.
\item \textbf{Quantified} the distinction between exact injected-bias classification and detecting an attack of a given bias level, reporting classwise recall together with normal false alarms and repeated-holdout variability.
\item \textbf{Compared} source-only transfer, supervised adaptation, and target-only training, and measured the accuracy--processing-cost tradeoff of LF/HF/TD representations and validation-ranked feature subsets.
\end{itemize}'''+s[b:]
